package com.halftonestudio;
import java.util.*;
public final class PerfectPortraitMazeTest {
 public static void main(String[] args){int w=160,h=192;int[] p=new int[w*h];for(int y=0;y<h;y++)for(int x=0;x<w;x++){int v=(x*255)/(w-1);p[y*w+x]=0xff000000|v*0x10101;}
 int runs=0;for(PerfectPortraitMaze.Mode mode:PerfectPortraitMaze.Mode.values())for(double mm:new double[]{101.6,203.2,279.4})for(int d=0;d<4;d++){PerfectPortraitMaze.Options o=new PerfectPortraitMaze.Options();o.mode=mode;o.widthMm=mm;o.difficulty=d;o.seed=566+d;PerfectPortraitMaze.Result r=PerfectPortraitMaze.generate(p,w,h,null,o);int[] g=r.passages(),route=r.solutionCells();long sum=0;for(int v:g)sum+=Integer.bitCount(v);if(sum!=2L*(g.length-1)||route[0]!=r.start||route[route.length-1]!=r.finish||r.wallFloorMm<o.minWallMm||r.passageFloorMm<o.minPassageMm||r.wallLoops().isEmpty())throw new AssertionError(r.report());Set<Integer> visited=new HashSet<>();for(int i:route)visited.add(i);if(visited.size()!=route.length)throw new AssertionError("Repeated route");runs++;}
 PerfectPortraitMaze.Options o=new PerfectPortraitMaze.Options();o.widthMm=101.6;PerfectPortraitMaze.Result a=PerfectPortraitMaze.generate(p,w,h,null,o),b=PerfectPortraitMaze.generate(p,w,h,null,o);if(!a.svg(true,0xff000000).equals(b.svg(true,0xff000000)))throw new AssertionError("Non-deterministic");boolean[] mask=new boolean[p.length];Arrays.fill(mask,true);mask[5]=false;try{PerfectPortraitMaze.generate(p,w,h,mask,o);throw new AssertionError("Accepted destructive crop");}catch(IllegalArgumentException expected){}System.out.println("PASS "+runs+" maze cases, determinism, destructive mask rejection");}
}
